export type ItemClassName = (typeof ITEM_CLASS_NAMES)[number]

export function itemClassName(id: ItemId): ItemClassName {
  return ITEM_CLASS_NAMES[id] ?? 'Unknown'
}

export function itemIdFromClassName(
  className: string | null | undefined
): ItemId | undefined {
  if (!className || className === 'Unknown') return undefined
  const id = (ITEM_CLASS_NAMES as readonly string[]).indexOf(className)
  return id < 0 ? undefined : (id as ItemId)
}

